#!/usr/bin/env python3
"""Writes AMENDMENT_A17.md and AMENDMENT_A18.md (+ sidecars). Facts only. Refuses to overwrite. Written BEFORE the code they govern and before any of their results exist."""
import hashlib, datetime, json
from pathlib import Path
from zoneinfo import ZoneInfo
ROOT = Path(__file__).resolve().parent.parent; A17 = ROOT / "AMENDMENT_A17.md"; A18 = ROOT / "AMENDMENT_A18.md"; assert not A17.exists() and not A18.exists()
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest(); now = datetime.datetime.now(datetime.timezone.utc)
stamp = f"Dated {now.isoformat()} UTC ({now.astimezone(ZoneInfo('America/New_York')).isoformat()} New York)."
rec = json.loads((ROOT / "section5/results/main_run/run_complete.json").read_text())
cited = ["SECTION5_PROTOCOL.md", "AMENDMENT_A16.md", "section5/results/main_run/run_complete.json", "section5/results/main_run/run_summary.json", "section5/results/contamination_list.json",
         "section5/results/posthoc_main_run.json", "section5/s5_backend.py", "section5/s5_run.py", "section5/s5_h1c.py"]
def table(): return ["| Document | SHA-256 |", "|---|---|"] + [f"| `{f}` | `{sha(ROOT / f)}` |" for f in cited]
NOTE = ("Not integrated into `SECTION5_PROTOCOL.md` now: integrating it would change the protocol hash, and A16 rule 6 binds the main run's checkpoints and completion record to that hash, so the "
        "main run would have to be redone before the freeze. The amendment is adopted as this dated, hashed file; integration is deferred until after the 5.12 freeze, and the freeze call must list it "
        "in its amendments argument (the freeze's input hashes cover only amendments the protocol integrates).")

L = ["# Amendment A17 (deterministic reproduction of the main-run fits; H1(c); post-hoc R=1-net H1(a); test-segment QLIKE percent)", "",
     f"{stamp} Status: ADOPTED when committed with its hash sidecar; written before the code it governs and before any of its results. Decided by the user after the main run. Facts only.", "",
     "## Evidence cited", ""] + table() + [
     "", f"Main run: completion record sha256 `{sha(ROOT / 'section5/results/main_run/run_complete.json')}`, results sha256 `{rec['results_sha256']}`, code version `{rec['code_version']}`, protocol `{rec['protocol_sha256']}`.", "",
     "## Rules", "",
     "1. Reproduction. Before anything else the script verifies the main-run completion record (A16 rule 1) and that the current code version equals the record's. Per fold (34, consecutive order) and family (4), it calls the main path's `score_fold` with the stored setup (features, params, base_params; 3 starts, seed 0, the same backend). Every field of the result (H1(a) effect and skip/failure reason, H1(b) effect, n, DM statistic, validation QLIKE, flag) must equal the stored checkpoint value exactly (NaN equal to NaN); on any mismatch the run stops with the details recorded and exit code 4, and nothing further (including A18) runs. The fitted feature and baseline models are saved (pickle, sha256 in a committed manifest; the pickles themselves stay local).",
     "   - WHY: H1(c), the placebo gap and the test QLIKE levels need the fitted models, which the main run did not store; an exact match shows the models are the main run's. EVIDENCE: `posthoc_main_run.json` (not computable from stored outputs); the fits are deterministic (seed 0, same code version).",
     "2. Alarm times. Per fold and family, a threshold for the feature model and one for the baseline model are set by the A7 rule on that fold's real validation sessions (bisection to 0.2 confirmed alarms per session; bounds theta [0, 30], m [1, 80]; flags as A7) - the fold-level reading of 'the frozen alarm frequency' (the era-level thresholds of 5.13 do not exist before the freeze). Confirmed alarms on every test session are saved: minute of T_d and T_c after 09:30 (slot + 1, the availability minute). Detectors: `detect_old_state_logodds` (HMM, HSMM), `detect_bocpd_map` (BOCPD).",
     "3. H1(c) as pre-registered (A8 item 5, A11 item 3, A12 item 2): the 98 eligible events of the canonical contamination list with their release minutes; a hit = a confirmed alarm with availability in [release, release + 60 min]; features versus baseline per family; paired exact sign test (two-sided, `s5_h1c.paired_sign`), Wilson 95% intervals; reference rate = share of the same fold's non-FOMC test sessions with an alarm in the same clock window, averaged over events; outside Holm (secondary). All four families reported.",
     "4. POST HOC, labelled as such: per-fold R=1 placebo gap. Placebo splices are built from the fold's stable test days exactly as the A8.1/A8.2 gate builds them (`build_specs` with ratio 1, direction up, durations permanent/30/60/120, 50 per duration = 200, seed 777); the null alarm rate x comes from the fold's H1(a) null splices; gap = pAUC_placebo(features) - pAUC_placebo(baseline); net H1(a) = H1(a) - gap; folds skipped for H1(a) are skipped. Net H1(a) is tested with the 5.9 machinery (block bootstrap, Wilcoxon, sign) and reported beside H1(a); no decision changes.",
     "5. Test-segment QLIKE percent: per fold, 100 x (mean baseline QLIKE - mean feature QLIKE) / mean baseline QLIKE on the common scored test bars (the bars H1(b) uses); median, quartiles and pooled value per family; confirmatory and all folds.",
     "6. Contamination: these runs fit models on, and score detectors on, the main run's fold segments after the confirmatory H1 had been scored. Registry category POST_MAIN_RUN: does not mark sessions touched for the frozen 5.14 list (it protects the H1 fold scores, which precede these runs); no fold-level confirmatory use of these outputs. No era calibration, no lock, no freeze, no evaluation data.",
     "", "## Governs", "", f"`s5_a17.py`, `s5_a17_a18_common.py`, registry entries, unit tests, the overnight wrapper; results under `section5/results/a17/`. {NOTE}"]
A17.write_bytes(("\n".join(L) + "\n").encode("utf-8")); A17.with_suffix(".sha256").write_text(f"{sha(A17)}  {A17.name}\n", encoding="ascii")

M = ["# Amendment A18 (pre-registered sensitivity: selection by one-step-ahead predictive log-likelihood of the next 5-min SPY return)", "",
     f"{stamp} Status: ADOPTED when committed with its hash sidecar; pre-registered: decided before any of its results exist, written before the code it governs. Decided by the user after the main run. Facts only.", "",
     "## Evidence cited", ""] + table() + ["",
     "## Rule", "",
     "1. Per fold, 5.8 selection is rerun with one change: the validation objective is the mean negative one-step-ahead predictive log-likelihood (nats per scored bar) of the next decision bar's deseasonalised 5-min SPY return, in the inner-train-fitted preprocessing scale (the return column after winsorisation and z-scoring; identical for every candidate of a fold). Lower is better. Everything else is identical: greedy forward from the return-only model at K=3 / lambda=39 with 1 start, the 1% relative-gain stop (gain = (current - candidate) / |current|), at most 6 features, K/lambda tuning with 3 starts, the baseline tuned the same way (A15 rule 1), tie rules, scoring (H1(a) pAUC, H1(b) QLIKE), tests, Holm.",
     "2. Predictive density at bar t+1 given updates up to t, within a session, for t+1 >= 2nd update and a finite return at t+1: Gaussian and Student-t HMM: filtered state probabilities at t times the transition matrix, mixed over the states' marginal density of the return column (Normal; Student-t with the state's df and scale); HSMM: the one-step prediction of the expanded (state, duration) forward variable, mixed over the states' Normal return marginal; BOCPD: the run-length posterior after t mixed over each run length's Student-t predictive of the return column. Skipped updates follow 5.3 (transition or hazard only).",
     "3. Reports: per model family the selected features and feature families (D1 style, the name-stem families of `s5_posthoc_main.py`); H1(a)/(b) fold tests, IU and Holm under these setups, confirmatory (26 folds) and all folds; the share of folds selecting at least one non-volatility feature. Volatility families (fixed now): rv, downside, abs_return, intrabar_range. Non-volatility families: momentum, return, relative_volume, close_location.",
     "4. Status: sensitivity analysis. It does not replace the 5.8 setups, the H1 verdicts or the setups to be frozen in 5.12. Runs after A17 in the same unattended wrapper. Contamination category POST_MAIN_RUN (A17 rule 6). Its run directory gets a completion record with backend kind 'a18-<script hash>', which can never verify as a main record.",
     "", "## Governs", "", f"`s5_a18.py`, `s5_a17_a18_common.py`, registry entries, unit tests, the overnight wrapper; results under `section5/results/a18/`. {NOTE}"]
A18.write_bytes(("\n".join(M) + "\n").encode("utf-8")); A18.with_suffix(".sha256").write_text(f"{sha(A18)}  {A18.name}\n", encoding="ascii")
print("A17", sha(A17)); print("A18", sha(A18))
